/*
 * BrakeData: CAN ID 0x300 (standard), 6 bytes, sender ABS, cycle time 20 ms
 *
 * C struct generated by CanViewer from demo.dbc.
 * Each member holds the raw value of a signal; physical value = raw * factor + offset.
 */
#include <stdint.h>

#define BRAKEDATA_ID 0x300u
#define BRAKEDATA_IS_EXTENDED 0
#define BRAKEDATA_LENGTH 6u

typedef struct {
    /* start bit 7, 16 bits, Motorola, unsigned, factor 0.01, offset 0, range 0 .. 655.35 km/h */
    uint16_t WheelSpeedFL;
    /* start bit 23, 16 bits, Motorola, unsigned, factor 0.01, offset 0, range 0 .. 655.35 km/h */
    uint16_t WheelSpeedFR;
    /* start bit 39, 10 bits, Motorola, unsigned, factor 0.5, offset 0, range 0 .. 511.5 bar */
    /* Master cylinder pressure. */
    uint16_t BrakePressure;
    /* start bit 45, 1 bit, Motorola, unsigned, factor 1, offset 0, range 0 .. 1 */
    uint8_t AbsActive;
} BrakeData_t;
